from .common import *
def main():
    I=read(BASE/'INTERPRETATION.json');sel=read(BASE/'SELECTED_FROZEN.json')['selected'];by={r['id']:r for r in read(BASE/'ALL_RUNS.json')};low=read(BASE/'LOW_PRESSURE_ADMISSION.json');baseline=read(BASE/'BASELINE_VALIDATION.json');comp=read(BASE/'OPTIMIZER_COMPARISON.json');audit=read(BASE/'AUDIT.json');stress=read(BASE/'ROBUSTNESS_RUNS.json');workflow=read(BASE/'WORKFLOW_COMPLETE.json')
    label='EXPLORATORY · HOMOGENEOUS_WATER_CONTROL_PROXY · PHYSICS_UNCALIBRATED · ELECTRICAL_TO_ACOUSTIC_UNCALIBRATED · training_ready=false'
    def doc(name,title,body):
        (BASE/(name+'.md')).write_text('# '+title+'\n\n'+body+'\n\n'+label+'\n')
    def table(headers,rows):return '\n'.join(['| '+' | '.join(headers)+' |','| '+' | '.join(['---']*len(headers))+' |']+['| '+' | '.join(str(v) for v in r)+' |' for r in rows])
    summary=table(['Target','Frozen source','Discovery aspect change','COM (nm)','Independent confirmations','Final test raw hits','Confirmed'],[[k,v['source'],f'{v["discovery"]["aspect_gain"]*100:.4f}%',f'{v["discovery"]["COM_m"]*1e9:.4f}',f'{v["validation_confirmed"]}/3',f'{v["final_test_raw_pass"]}/3',v['confirmed']] for k,v in I['targets'].items()])
    actiontable=table(['Target','Frequency (MHz)','A [Y-/Y+/X-/X+] (Pa-eq)','Phase (deg)'],[[k,f'{v["task"].get("frequency",2.5e6)/1e6:g}',' / '.join(f'{x:.5f}' for x in v['task']['amplitudes']),' / '.join(f'{np.degrees(x):.4f}' for x in v['task']['phases'])] for k,v in sel.items() if k!='T4'])
    costs=table(['Method','Observations','Complete','COM-feasible','Raw hits','First hit','Charged wall (s)','Ask/tell (s)'],[[r['method'],r['observations'],r['complete'],r['feasible'],r['raw_target_hits'],r['first_target_observation'],f'{r["wall_s"]:.3f}',f'{r["optimizer_s"]:.3f}'] for r in comp['methods']])
    doc('README','F10AE 实际交付',f'本轮完成指定形态、绝对主轴伸长和两段恢复的有限逐泡实验。发现集达标、独立验证、最终测试及数值质量分别报告。\n\n{summary}\n\n完整答复见 [FINAL_CHINESE_REPORT.md](FINAL_CHINESE_REPORT.md)。12 组 PNG/PDF 位于 `figures/`，3 段真实固定 ID 视频位于 `videos/`。大型逐步 HDF5 与 APECSS 原始轨迹保留在服务器，便携数据位于 `dataset/`。')
    doc('ACTIVE_CODE_INDEX','Active F10AE code',table(['Module','Role'],[['common.py / protocol.json','Paths, protected hashes, preregistered targets and budgets'],['low_pressure.py / response.py / low_admit.py','Official APECSS refinement and explicit opt-in low intervals'],['run.py','Original F10AA Campaign.run and AuditEngine; no new physics solver'],['metrics.py / schedules.py','Separate target/recovery labels and existing fixed-frequency schedules'],['baseline.py','Historical and two-segment regressions'],['search.py','Official Ax/BoTorch and SciPy Sobol comparison'],['explore.py','Static force/mobility diagnostics, 8 full extension and 32 recovery candidates'],['validate.py','Three unseen validation seeds; frozen final tests; frequency/shell/position'],['audit.py / interpret.py','Independent per-step force/contact reconstruction and scientific gates'],['figures.py / videos.py','Publication plots and exact saved frames'],['report.py / finalize.py','Reports, historical protection, artifact hashes']]))
    doc('BASELINE_AND_MODEL_AUDIT','Baseline and model audit','Baseline Git `baa47dbe95c78e1800aebe50bc3efc5faf07d5fa`; new isolated branch `dev/f10ae-targeted-shape-recovery-20261019`. The source execution commits are recorded per run. Historical F10AC/F10AD extracted snapshots were audited rather than replaced from GitHub.\n\nAll three historical elite position histories reproduced bitwise. N=64, equilibrium radius 1.78 um, strict zero flow. Original SciPy resistance/contact and Warp acoustics remain unchanged. The 32.5 x 9 x 9 mm water-filled cavity and four 7 mm discs are reused; no PDMS elastic/acoustic boundary calibration is claimed.\n\nHistorical 2.5 MHz pressure table: 0.1–40000 Pa. F10AD frequency tables: 0.001–12000 Pa. Those remain distinct. See `LOW_PRESSURE_TABLE_AUDIT.json` for exact metadata and SHA-256.')
    doc('LOW_PRESSURE_APECSS_AUDIT','Low-pressure APECSS audit','Official APECSS commit `a0ee071ca247b5489e997d90e83b5f53c40e4ec7`, unchanged RPAR / reversible Marmottant model. 27 actual radial attempts: pressure nodes and independent midpoints, 48/96/192 cycles, 512/1024/2048 samples per cycle and tightened tolerances. The 0.0001 Pa finest attempt timed out at 120 s; its raw output is preserved and this domain is excluded.\n\nValidated diagnostic suffix: 0.001–1 Pa. Complex harmonic and volume-rate energy errors are used; small noisy phase angles are not independently interpolated. Genuine F1/F2 values and CPU/GPU relative comparisons are in `LOW_PRESSURE_FINAL.json`. The final explicit low-pressure trajectories use source 0.003 Pa-equivalent, with actual incident pressure below 0.1 Pa. The older nominal 0.1 Pa-equivalent tests produced about 0.37 Pa locally and are not used alone as low-incident-pressure proof.\n\nThe earlier three failures are independently reconstructed at the last accepted state, not mislabeled as the failed kernel force.')
    doc('LOW_PRESSURE_RESPONSE_EXTENSION','Low-pressure response extension',f'Final opt-in extension admitted: **{low["production_extension_admitted"]}**. New lower limit 0.001 Pa at 2.5 MHz, original shell x1 and R=1.78 um only. All original >=0.1 Pa intervals and CPU queries are retained exactly. The 0.1 Pa join differs from the refined direct response by about 4.84e-6 relative. No clipping, frequency interpolation, extrapolation, or near-zero force cutoff.\n\nThree prior domain-failed actions complete in new explicitly named joined-table trials. Earlier historical runs are untouched. A separate frozen-action followup of the F10AE final_T4_1 failure reaches 0.966 ms rather than 0.237 ms under the admitted extension, but still fails the response-domain guard; no endpoint is assigned and the original final test remains failed. See LOW_DOMAIN_FOLLOWUP.json.\n\nThe initial admission summary was conservatively false because a NumPy Boolean was tested by identity. The extra `low_admit.py` phase both fixes aggregation and adds explicit sub-0.1 Pa incident-pressure dynamics. Search/validation had consistently retained the historical production domain; no comparison was switched halfway. `LOW_PRESSURE_ADMISSION.json` is the authoritative final opt-in gate; `LOW_PRESSURE_FINAL.json` remains as earlier evidence.')
    doc('TARGET_DEFINITIONS','Target definitions','T1: aspect gain 3% ±0.5 percentage points; COM ≤20 nm; complete numerical trajectory. The three labels remain independent. T2: aspect gain 0.4% ±0.2 percentage points and endpoint connected; all-time connectivity separate. T3: an absolute sorted principal RMS length increase above max(1 nm, 5 times dt/cache noise); distribution splitting is separated from connected-group deformation. Near-degenerate orientations are invalidated.\n\nT4: >=50% recovery and final relative Rg / all-axis errors ≤0.5%, aligned covariance error ≤1%, fixed-ID Kabsch RMS ≤5 nm, neighbor Jaccard ≥0.95. Each recovery level is separate and must improve on OFF. These criteria were frozen in protocol.json before trajectories. Fixed IDs are never reassigned.')
    doc('OPTIMIZER_REUSE_AND_SELECTION','Open-source optimizer reuse','Official [Ax Client](https://ax.dev/docs/tutorials/getting_started/) and its [outcome constraints](https://ax.dev/docs/recipes/outcome-constraints/) are used with BoTorch, not a home-written Gaussian process or acquisition function. The comparator is [SciPy Sobol](https://docs.scipy.org/doc/scipy/reference/generated/scipy.stats.qmc.Sobol.html). Installed versions and licenses are in `evidence/DEPENDENCIES.json`.\n\nTwo continuous parameters: X pair common amplitude 200–1100 Pa-equivalent and relative phase 150–240 degrees. Both methods receive the same 8 starting observations and 32 total observations each, representing 56 distinct new full simulations. Failed solves are marked failed, with no endpoint loss. Ax models COM_nm ≤20 as an outcome constraint.\n\nNevergrad is installed but NOT_RUN: two mature methods sufficed for this bounded comparison. Winner expansion beyond the frozen initial comparison is NOT_RUN; budget is reserved for recovery and independent validation. One optimizer seed does not establish general superiority.\n\n'+costs)
    doc('CONSTRAINED_OPTIMIZATION_RESULTS','Constrained optimization results',costs+'\n\nAx reached a discovery-feasible T1 point at observation 10, Sobol at 26. Ax produced 9 raw target hits, Sobol 1, with about 10.3 s optimizer overhead. These are discoveries on S2_r0; independent target confirmation is separately shown below.\n\n'+summary)
    doc('TARGETED_SHAPE_TRANSFORMATION','Targeted shape transformation',summary+'\n\n'+actiontable+'\n\nEach initial state is a separately generated connected geometric configuration. It is a demonstration initial condition, not an acoustic aggregation claim. Endpoint connected does not imply physical fusion or adhesion.')
    ex=I['extension'];doc('ABSOLUTE_EXTENSION_SEARCH','Absolute extension search',f'128 bounded static force/mobility queries; 8 highest principal-axis free-rate candidates receive full 2 ms trajectories. Amplitudes ≤1100 Pa-equivalent, X/Y relative phases within 0–360 degrees, fixed 2.5 MHz. Full results, including failures, are in STATIC_EXTENSION.json and EXTENSION_RUNS.json. No active discovery action exceeded the absolute-extension floor; OFF is retained as the explicitly non-extending T3 reference. However, validation states show numerically resolved global L1 growth of 1.186 and 2.218 nm, with 3 and 2 components respectively. A final test has connected global L1 growth of 7.808 nm but lacks a refinement on that test state. These are post-hoc state-specific observations, not a confirmed cross-state target. Their largest 62-particle same-ID components instead have L1 changes of -2.046 and -0.238 nm: the resolved global growth does not establish internal extension of the largest connected group. See SEED_SPECIFIC_EXTENSION.json for that decomposition.\n\nRaw >1 nm extension trajectories: {len(ex["raw_above_1nm_ids"])}. Independently confirmed selected T3: {ex["confirmed"]}.\n\nThe global fixed-ID distribution and same-ID largest component are separated. A rise in aspect with all three principal RMS lengths shrinking is ANISOTROPIC_CONTRACTION. ABSOLUTE_EXTENSION_NOT_FOUND_IN_TESTED_DOMAIN applies only to the discovery S2_r0 scan. It does not erase the seed-specific positive observations and is not a proof of global physical uncontrollability.')
    doc('TWO_STAGE_SCHEDULE_VALIDATION','Two-stage schedule validation',f'Continuous 4 ms and two identical 2 ms actions: maximum fixed-ID difference {baseline["schedule"]["errors"]["fixed_id_m"]:.4g} m; clock strictly increasing, one switch at 2 ms. First active 2 ms then OFF: second-stage maximum motion {baseline["schedule"]["OFF_stage_displacement_m"]:.4g} m. No dropped or duplicated integration step. Four independent source amplitudes/phases retain the common harmonic phase reference.\n\nQUASISTEADY_RADIAL_RESPONSE_AT_SWITCH. Actual radial ringdown and actual instrument phase-switch transients: NOT_RUN. These results describe ideal steady-table piecewise controls, not a measured transient experiment.')
    rec=I['recovery'];rectable=table(['Metric','At switch error','Active endpoint error','OFF endpoint error','Recovery fraction'],[[k,f'{rec["result"]["first_errors"][k]:.6g}',f'{rec["result"]["final_errors"][k]:.6g}',f'{rec["OFF"]["final_errors"][k]:.6g}',rec['result']['recovery_fraction'].get(k)] for k in ['Rg','axes','covariance','Kabsch_m','pair_distance_m','neighbor_error']])
    doc('DEFORMATION_AND_RECOVERY','Deformation and recovery',f'First action: X pair 700 Pa-equivalent, 180 degrees, 2 ms; numerical regression precedes recovery. Thirty-two 4 ms candidate protocols were attempted; 31 completed and one failed before the endpoint: 16 X-pair second actions, then 16 bounded X/Y combinations. No reverse playback or invented restoring force. Selected active candidate: `{rec["source"]}`.\n\n'+rectable+'\n\nRecovery levels: '+json.dumps(rec['confirmed_levels'])+'\n\nRg recovery is never substituted for structure or topology recovery. At a zero initial topology error, unchanged edges are maintenance, not evidence of a restoration process.')
    robusttable=table(['Case','Status','Aspect change (%)','Rg change (%)','COM (nm)'],[[r['id'],r['status'],f'{r["targets"]["aspect_gain"]*100:.5g}' if r['targets'] else 'NO_ENDPOINT',f'{r["targets"]["Rg_gain"]*100:.5g}' if r['targets'] else 'NO_ENDPOINT',f'{r["targets"]["COM_m"]*1e9:.5g}' if r['targets'] else 'NO_ENDPOINT'] for r in stress])
    doc('FREQUENCY_ROBUSTNESS','Frequency robustness',robusttable+'\n\nEach 2.4/2.5/2.6 MHz test uses its own admitted field, gradient, response and F1/F2. Same frozen actions, no new optimization at each frequency. Half-step and fine-cache comparisons are in ROBUSTNESS_CONVERGENCE.json; accepted integration alone does not establish numerical admission. New small frequency offsets: NOT_RUN. Three discrete frequencies cannot establish a universal frequency ranking.')
    doc('SHELL_AND_POSITION_SENSITIVITY','Shell and position sensitivity',robusttable+'\n\nShell elasticity x0.8/x1.2 uses corresponding actual F10AD tables. Spatial tests shift the entire legal initial cloud by Y ±5 um. Explicit Y-pair controls probe the near-field node independently of whether the chosen action uses Y. PROXY_SENSITIVE_MODE denotes observed node/parameter dependence, not a measured PDMS property. The nominal 2.5 MHz production table and shell-variant rebuilt tables have separate provenance; this difference limits interpretation of tiny shell effects.')
    doc('INDEPENDENT_INITIAL_STATE_VALIDATION','Independent initial-state validation',summary+'\n\nValidation seeds: 461901/461902/461903. Final test seeds: 461951/461952/461953. S2_r0 is discovery. Selected actions were frozen before validation; test actions are run once without subsequent retuning. Each validation action has DT1, DT05 and fine-cache runs. Final tests provide new raw target outcomes, not a separate refinement study. Statistical unit is one initial-state/action trajectory, never its thousands of time steps.')
    n=I['numerics'];doc('NUMERICAL_CONVERGENCE','Numerical convergence',f'DT05 comparisons passed: {n["step_pass"]}/{n["step_total"]}; fine-cache: {n["cache_pass"]}/{n["cache_total"]}. Original fixed-ID limit 50 nm and all original group metrics retained. Independent all-step reconstruction passed for all complete trajectories: {audit["all_completed_independent_pass"]}; checked steps: {audit["checked_steps"]}.\n\nFailures are retained in INTERPRETATION.json, including full-window target failures and numerical comparison failures. Proximity-edge timing is reported separately; small hard-contact event changes are not hidden by a smooth animation.')
    doc('FAILURE_AND_NEGATIVE_RESULTS','Failures and negative results',f'Physical attempts: {I["physical_attempts"]}; complete: {I["complete"]}; incomplete: {len(I["failures"])}. Radial 0.0001 Pa finest solve timed out. All original raw attempted states, forces, exceptions and accepted prefixes remain. Failed integrations have `final=null` and no target loss.\n\n'+summary+'\n\nNumerical comparison rejects: '+json.dumps(n['rejected'],ensure_ascii=False,indent=2)+'\n\nPhysical failures: '+json.dumps(I['failures'],ensure_ascii=False,indent=2))
    doc('CPU_GPU_RESOURCES','CPU/GPU resources',costs+f'\n\nScientific workflow wall: {workflow["wall_s"]:.3f} s. It includes baseline, search, extension, recovery and validation orchestration, but not initial environment downloads, radial audit, later artifact rendering or the additional low-pressure admission. Final cost ledger records those separately. Per-run solver/integration/postprocessing wall, process CPU and RSS are in ALL_RUNS.json. Resource samples are in RESOURCES.jsonl.\n\nFour independent processes; OMP/OpenBLAS/MKL/NumExpr each one thread. RTX 4090 runs Warp acoustics; Ax uses CPU Torch. An unrelated CPU task was present; this is an observed campaign throughput, not an exclusive hardware benchmark. Effective scientific target yield is based on independent confirmation, not raw high scores.')
    doc('EXECUTION_AND_REPRODUCTION','Execution and reproduction','Local branch: `dev/f10ae-targeted-shape-recovery-20261019`. Server root: `/workspace/mevo_acoustic_microbubbles/f10ae_target_20261019`. Isolated copied environment plus pinned optimizer installation; full freeze and logs in evidence/server_logs. Source is exported from clean Git commits into immutable `execution/<commit>_<label>` snapshots. Jobs use independent `mevo_f10ae_*` Supervisor labels and timeouts.\n\nFrom a fresh isolated execution with read-only historical dependencies: `PYTHONPATH=src:. .venv/bin/python -m scripts.straight_tube_exp1.f10ae.prepare`, then `low_pressure`, `workflow`, and `post`. Existing IDs are immutable and hashed; create a fresh result root for a new campaign. `SOURCE_F10AE_COMMIT.txt` and per-run F10AE_INPUT.json provide the actual code/input identity.\n\nDo not overwrite historical stage results or launch hardware. Portable datasets store exact saved accepted frames, with each file recording its sampling; original all-step HDF5 remains on the server. Videos map to actual raw indices. No fabricated frames or state interpolation.')
    doc('FINAL_RECOMMENDATION','Final recommendation','优先将“发现初态可达”与“跨初态可靠可达”分开。下一轮如继续，应冻结更窄的动作域，在多个独立发现初态上优化有明确容差的目标，并给单独测试集留预算；不要反复在最终测试集调参。\n\n若恢复实验没有真正反向变化，应先用小规模静态去均值力和受阻速度诊断寻找第二个独立形变方向，再决定是否值得延长轨迹。应补做切换径向瞬态和实验四源声场/相位标定；不能通过人为恢复力或改接触预算制造可逆性。当前不开展世界模型训练，training_ready=false。')
    if (BASE/'COMPUTE_COST.json').exists():
        cost=read(BASE/'COMPUTE_COST.json')
        resource_text='\n\nFinal measured ledger: core scientific wall %.3f s (%.2f min); latest figures and videos %.3f s. Median / p95 / max complete solver wall: %s s. Incomplete fraction %.4f. Independently confirmed target count %d; confirmed targets/core-hour %.3f. Per-process peak RSS %.1f MiB. Resource samples: %s. Exclusions: %s\n' % (cost['nonoverlapping_core_scientific_wall_s'],cost['nonoverlapping_core_scientific_wall_s']/60,cost['latest_figures_and_videos_wall_s'],cost['solver_complete_wall_s'],cost['incomplete_fraction'],cost['independently_confirmed_target_count'],cost['confirmed_targets_per_core_hour'],cost['process_rss_peak_MiB'],json.dumps(cost['resource_sampling']),cost['time_scope'])
        with (BASE/'CPU_GPU_RESOURCES.md').open('a') as f:f.write(resource_text)
    answers=[]
    answers.append('低压边界已有限扩展至 0.001 Pa（仅 2.5 MHz、原壳参数、R=1.78 µm）；0.0001 Pa 的精细求解超时而未准入。最终准入 '+str(low['production_extension_admitted'])+'，完整证据见 LOW_PRESSURE_ADMISSION.json。')
    answers.append('旧表、旧轨迹保留；三个历史 elite 逐位复现；新增区间明确 opt-in。发现搜索仍统一采用旧域；此前三条越界轨迹在新命名的接表重算中完成。')
    answers.append('本次单个优化种子下，Ax/BoTorch 对指定 T1 目标优于 Sobol；这是有限范围结论。')
    answers.append('发现集第一次达标需 10 次观察，Sobol 为 26 次；各 32 次观察，8 个共享起点，实际独立新物理调用 56 次。')
    answers.append(f'Ax 拟合/建议/反馈累计 {comp["methods"][1]["optimizer_s"]:.3f} s；实际整段比较墙钟 {comp["wall_s"]:.3f} s。')
    for k in ['T1']:
        v=I['targets'][k];answers.append(f'T1 发现状态长宽比增加 {v["discovery"]["aspect_gain"]*100:.4f}%；3 个独立验证确认 {v["validation_confirmed"]}/3，最终测试原始命中 {v["final_test_raw_pass"]}/3；稳定确认={v["confirmed"]}。')
    answers.append(f'T1 发现态 COM 漂移 {I["targets"]["T1"]["discovery"]["COM_m"]*1e9:.4f} nm，20 nm 约束单列；跨初态数据见 VALIDATION.json。')
    v=I['targets']['T2'];answers.append(f'T2 独立确认 {v["validation_confirmed"]}/3，最终测试命中 {v["final_test_raw_pass"]}/3；完整确认={v["confirmed"]}。终点与全程连通分开，均为几何邻近而非融合。')
    v=I['targets']['T3'];answers.append('发现初态上未找到超过门槛的主动绝对伸长，故 T3 保留 OFF 参考且目标未确认。但新验证初态出现 L1 +1.186 nm、+2.218 nm，分别超过其 5 倍 dt/cache 轴差（约0.00147 / 0.00274 nm）和1 nm门槛，属于已数值分辨的、初态相关的分布伸长；终点分为3/2个邻近分量；最大62泡子群按相同ID回溯后的 L1 反而分别变化 -2.046 / -0.238 nm，不能称为该连通子群内部拉伸。最终测试还出现连通态 +7.808 nm，未对此留出初态追加步长复核，不能升级为稳健连通团拉伸。详见 SEED_SPECIFIC_EXTENSION.json。')
    answers.append('测试域：X 对 200–1100 Pa-eq、150–240° 目标搜索；128 个四源静态诊断，振幅 ≤1100 Pa-eq、相位 0–360°，8 条完整伸长候选。失败只说明该有限测试域尚未确认，不能证明全局不可控。')
    for gate in ['RG_RECOVERY_PASS','PRINCIPAL_AXIS_RECOVERY_PASS','FIXED_ID_CONFIGURATION_RECOVERY_PASS','TOPOLOGY_RECOVERY_PASS']:answers.append(f'{gate}：{rec["confirmed_levels"][gate]}。分别按自身误差、恢复比例、OFF 比较和独立验证判定。')
    answers.append('主动第二段相对 OFF 的误差差值（负数才是改进）：'+json.dumps(rec['active_minus_OFF_errors'])+'。是否达到恢复容差不能用微小改进替代。')
    answers.append('理想分段采用 QUASISTEADY_RADIAL_RESPONSE_AT_SWITCH；没有模拟真实 AFG/PZT 切换、径向振荡建立和衰减瞬态。')
    answers.append('跨独立初态的确认汇总：'+', '.join(f'{k}: {v["validation_confirmed"]}/3' for k,v in I['targets'].items())+'。')
    answers.append('发现集命中但验证或最终测试未重复的动作只能称初态敏感候选，不能升级为稳健控制。具体每个初态见 INDEPENDENT_INITIAL_STATE_VALIDATION.md 和 VALIDATION.json。')
    answers.append(f'数值比较拒绝 {len(n["rejected"])} 个；固定 ID 50 nm 及原组级约束不放宽，具体动作与超差值全部保留于 INTERPRETATION.json。')
    answers.append('同一 T1 动作在 2.4/2.5/2.6 MHz 的长宽比变化为 5.453% / 2.997% / 7.015%；同一 T2 动作为 0.341% / 0.410% / 0.451%。所以没有跨动作通用的频率排序。未进行未经验证的频率插值。')
    answers.append('Y 对 700 Pa-eq、90° 在 Y=-5/0/+5 µm 的长宽比变化为 0.01970% / 0.01006% / 0.02105%；相对变化约两倍，但绝对形变很小。选定 T1 对 ±5 µm 较不敏感（约 2.997–3.002%）。压力、梯度和力方向见 ROBUSTNESS_FIELD_FORCE.json；所有 Y 推论限于均匀水代理。')
    answers.append('壳弹性 x0.8/x1.2 时，T1 长宽比变化为 3.667% / 2.156%，均偏离 3%±0.5pp；T2 为 0.484% / 0.298%。测试中仍是 Rg 下降、长宽比增加，方向未反转，但目标值不够鲁棒。这不是材料校准。')
    answers.append('本轮所有声学控制结论均仅在均匀水代理、当前壳与接触假设和短时间窗内有效，未校准真实 PDMS 或电压到声压映射。')
    answers.append('若继续寻找第二个独立形变方向，应先验证去均值力与阻力约束速度能产生稳定反向轴变化，再投入完整轨迹；同时检查频率、空间和初态鲁棒性。')
    answers.append('已有可追溯的有限动作数值数据，可用于后续受限观测接口研究；尚无足够校准和可逆形态覆盖支持世界模型训练准入，本轮未训练，training_ready=false。')
    assert len(answers)==25
    body='\n\n'.join(f'{i+1}. {a}' for i,a in enumerate(answers))
    combined=I['targets']['T1']['confirmed'] and all(rec['confirmed_levels'].values())
    body+='\n\n## 核心结论\n\n'+('本轮限定模型内的指定形态与恢复组合通过全部预登记条件。' if combined else '本轮不能声称已可靠实现“将微泡群变成指定三维形态并按需恢复”的组合能力。各个目标是否通过须分别看上表；有限搜索失败不是严格不可控证明。')+'\n\n'+summary+'\n\n'+costs+f'\n\n物理尝试 {I["physical_attempts"]} 条，完整 {I["complete"]} 条；科学工作流墙钟 {workflow["wall_s"]:.3f} s。最终总成本另见 COMPUTE_COST.json。'
    if (BASE/'COMPUTE_COST.json').exists():
        body+='\n\n包含低压径向验证、完整工作流、补充验证及独立逐步审计的核心科学耗时约 %.2f 分钟；本版绘图及视频生成另计 %.2f 分钟。不含安装、开发、网络回传、空等和重复渲染。' % (cost['nonoverlapping_core_scientific_wall_s']/60,cost['latest_figures_and_videos_wall_s']/60)
    doc('FINAL_CHINESE_REPORT','F10AE 最终中文科研报告',body)
    doc('F10AE_DEVELOPMENT_REPORT','F10AE development report',summary+'\n\nImplemented isolated experiments with official APECSS, original full-particle mechanics, Ax/BoTorch constraints, fixed-ID shape/recovery metrics, independent initial states and real scientific artifacts. No new particle solver or artificial restoration model. See the Chinese report for all 25 required answers, and FINAL_GATE.json for scoped machine-readable admission.')
